"""
    This method gets the affix information

    :param str text: Input text.
    """
def get_affix(text: Any) -> object {
    return " ".join([word[-4:] if (len(word) >= 4) else word for word in text.split()]);
}

"""Return the genome directory name from infra_id and optional arguments."""
def get_genome_dir(
    infra_id: Any, genver: Any = None, annver: Any = None, key: Any = None
) -> object {
    dirname = f"{infra_id}";
    if (genver is not None) {
        dirname += f".gnm{genver}";
    }
    if (annver is not None) {
        dirname += f".ann{annver}";
    }
    if (key is not None) {
        dirname += f".{key}";
    }
    return dirname;
}

